#include <bits/stdc++.h>
using namespace std;

string digits;
long long memo[20][1024][2][2];
bool done_[20][1024][2][2];

// Numbers whose remaining digits extend this state: position, used-digit mask,
// whether a non-zero digit has started, whether we are still tight against the bound.
long long dp(int pos, int mask, int started, int tight) {
    if (pos == (int)digits.size()) return 1;
    if (done_[pos][mask][started][tight]) return memo[pos][mask][started][tight];
    int top = tight ? digits[pos] - '0' : 9;
    long long answer = 0;
    for (int d = 0; d <= top; d++) {
        int nt = tight && d == top;
        if (!started && d == 0) answer += dp(pos + 1, mask, 0, nt);  // leading zeros use no digit
        else if (!(mask >> d & 1)) answer += dp(pos + 1, mask | 1 << d, 1, nt);
    }
    done_[pos][mask][started][tight] = true;
    return memo[pos][mask][started][tight] = answer;
}

// Count of distinct-digit integers in [0, limit].
long long countUpTo(long long limit) {
    if (limit < 0) return 0;
    digits = to_string(limit);
    memset(done_, 0, sizeof done_);
    return dp(0, 0, 0, 1);
}

int main() {
    long long l, h;
    cin >> l >> h;
    cout << countUpTo(h) - countUpTo(l - 1) << "\n";
}

import java.util.*;

public class Main {
    static String digits;
    static long[][][][] memo;

    // Numbers whose remaining digits extend this state: position, used-digit mask,
    // whether a non-zero digit has started, whether we are still tight against the bound.
    static long dp(int pos, int mask, int started, int tight) {
        if (pos == digits.length()) return 1;
        if (memo[pos][mask][started][tight] >= 0) return memo[pos][mask][started][tight];
        int top = tight == 1 ? digits.charAt(pos) - '0' : 9;
        long answer = 0;
        for (int d = 0; d <= top; d++) {
            int nt = tight == 1 && d == top ? 1 : 0;
            if (started == 0 && d == 0) answer += dp(pos + 1, mask, 0, nt); // leading zeros use no digit
            else if ((mask >> d & 1) == 0) answer += dp(pos + 1, mask | 1 << d, 1, nt);
        }
        return memo[pos][mask][started][tight] = answer;
    }

    // Count of distinct-digit integers in [0, limit].
    static long countUpTo(long limit) {
        if (limit < 0) return 0;
        digits = Long.toString(limit);
        memo = new long[digits.length()][1024][2][2];
        for (long[][][] a : memo) for (long[][] b : a) for (long[] c : b) Arrays.fill(c, -1);
        return dp(0, 0, 0, 1);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long l = sc.nextLong(), h = sc.nextLong();
        System.out.println(countUpTo(h) - countUpTo(l - 1));
    }
}

package main

import (
	"fmt"
	"strconv"
)

var digits string
var memo map[[4]int]int64

// dp counts the numbers whose remaining digits extend this state: position, used-digit mask,
// whether a non-zero digit has started, whether we are still tight against the bound.
func dp(pos, mask, started, tight int) int64 {
	if pos == len(digits) {
		return 1
	}
	key := [4]int{pos, mask, started, tight}
	if v, ok := memo[key]; ok {
		return v
	}
	top := 9
	if tight == 1 {
		top = int(digits[pos] - '0')
	}
	var answer int64
	for d := 0; d <= top; d++ {
		nt := 0
		if tight == 1 && d == top {
			nt = 1
		}
		if started == 0 && d == 0 {
			answer += dp(pos+1, mask, 0, nt) // leading zeros use no digit
		} else if mask>>d&1 == 0 {
			answer += dp(pos+1, mask|1<<d, 1, nt)
		}
	}
	memo[key] = answer
	return answer
}

// countUpTo counts distinct-digit integers in [0, limit].
func countUpTo(limit int64) int64 {
	if limit < 0 {
		return 0
	}
	digits = strconv.FormatInt(limit, 10)
	memo = map[[4]int]int64{}
	return dp(0, 0, 0, 1)
}

func main() {
	var l, h int64
	fmt.Scan(&l, &h)
	fmt.Println(countUpTo(h) - countUpTo(l-1))
}
